const llmOutputText = $input.first().json.text;
return [{ 
  json: { 
    video_ideas_array: JSON.parse(llmOutputText)
  } 
}];

const items = $input.all();
// return items[0].json
const inputQuery = items[0].json.input || "missing";

const simplified = items.map(item => ({
  title: item.json.title,
  thumbnail_summary: item.json?.text?.trim() || "Thumbnail summary missing.",
  views: item.json.viewCount || 0,
  subscribers: item.json.numberOfSubscribers || 0,
  upload_date: item.json.date || "unknown",
  hastags : item.json.hashtags && item.json.hashtags.length > 0
  ? item.json.hashtags
  : "No HashTags Found"

}));

return [
  {
    json: {
      input_query: inputQuery,
      videoDataForLLM: simplified
    }
  }
];
